topics.example:
@layer base, components, utilities;

:root { --space-3: .75rem; --accent: oklch(78% .15 210); }

@layer components {
  .course-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 18rem), 1fr));
    gap: var(--space-3);
  }
}

@layer utilities {
  .focus-ring:focus-visible { outline: 3px solid var(--accent); }
}

